    return map(lambda x: int(x) + offset, input().split())


def nia():
    return list(map(int, input().split()))


# CONVERT
def toString(aList, sep=" "):
    return sep.join(str(x) for x in aList)


def toMapInvertIndex(aList):
    return {k: v for v, k in enumerate(aList)}


# SORT
def sortId(arr):
    return sorted(range(len(arr)), key=lambda k: arr[k])


# MAIN

n,m,s = ni()

s -= 1

adj = [[] for _ in range(n)]

for i in range(m):
    u,v = nio(-1)
    if (v != s):
        adj[u].append(v)

stack = []

visited= [False]*n

def dfs(x):
    nonlocal visited
    nonlocal stack
    visited[x] = True
    for y in adj[x]:
        if not visited[y]:
            dfs(y)

    stack.append(x)


for i in range(n):
    if not visited[i]:
        dfs(i)

