class BIT():
    def __init__(self,n):
        self.BIT=[0]*(n+1)
        self.num=n

    def query(self,idx):
        res_sum = 0
        while idx > 0:
            res_sum += self.BIT[idx]
            idx -= idx&(-idx)
        return res_sum

    #Ai += x O(logN)
    def update(self,idx,x):
        while idx <= self.num:
            self.BIT[idx] += x
            idx += idx&(-idx)
        return

import sys,heapq,random

input=sys.stdin.readline

n=int(input())
spell=[tuple(map(int,input().split())) for i in range(n)]


S=set([])
for i in range(n):
    S.add(abs(spell[i][1]))
S=list(S)
S.sort(reverse=True)
comp={i:e+1 for e,i in enumerate(S)}
N=len(S)

x_exist=BIT(N)
y_exist=BIT(N)
power=BIT(N)

X,Y,S=0,0,0
Xmax=[]
Ymin=[]
x_data=[0]*(N+1)
y_data=[0]*(N+1)

for i in range(n):
    t,d=spell[i]
    S+=d
    if d<0:
        id=comp[-d]
