            heapq.heappush(Ymin,d)
            y_data[id]+=1
    if X==0:
        if Y==0:
            print(0)
        else:
            while not y_data[comp[Ymin[0]]]:
                heapq.heappop(Ymin)
            print(2*S-Ymin[0])
    else:
        if Y==0:
            print(S)
        else:
            start=0
            end=N
            while end-start>1:
                test=(end+start)//2
                if x_exist.query(test)+y_exist.query(test)<=Y:
                    start=test
                else:
                    end=test
            if y_exist.query(start)!=Y:
