class Solution:
    def longestOnes(self, A: List[int], K: int) -> int:
        hulu = []
        cnt = 0
        num = A[0]
        for x in A:
            if x == num:
                cnt += 1
            else:
                hulu.append([num,cnt])
                cnt = 1
                num = x
        if cnt>0:
