    def numSplits(self, s: str) -> int:
        left = [0]*len(s)

        unique = set()
        n_distinct = 0
        for i, l in enumerate(s):
            if l not in unique:
                unique.add(l)
                n_distinct += 1
            left[i] = n_distinct

