                    sLmax.append(sL[i])
                else:
                    sLmax.append(sLmax[-1])

            sM = [sum(A[-M:])]
            for i in range(N-M-1,L-1,-1):
                tmp = sM[-1]+A[i]-A[i+M]
                sM.append(tmp)
            sMmax = [sM[0]]
            for i in range(1,len(sM)):
                if sM[i]>sMmax[-1]:
