         :type s: str
         :rtype: bool
         """
         dot = False
         exp = False

         try:
             while s.startswith(' '):
                 s = s[1:]
             while s.endswith(' '):
                 s = s[:-1]
             if s.startswith('-') or s.startswith('+'):
                 s = s[1:]
