         :type grid: List[List[str]]
         :rtype: int
         """
         island_count = 0
         for i in range(len(grid)):
             for j in range(len(grid[i])):
                 if grid[i][j] == '1':
                     island_count += 1
                     self.expandIsland(grid, i, j)
         return island_count
