        v, u, w = map(int, a[1:])
        for x in get_way(u, v):
            if x not in d:
                d[x] = 0
            d[x] += w
    else:
        v, u = map(int, a[1:])
        res = 0
        for x in get_way(u, v):
            if x in d:
                res += d[x]
        print(res)
