comp = [-1] * n
def shortest(root):
    dist = [-1] * n
    q = [0] * n
    left, right = 0, 1
    q[left] = root
    dist[root] = 0
    good = True
    while left < right:
        x = q[left]
        left = left + 1
        for i in g[x]:
            if dist[i] is -1: 
                dist[i] = 1 + dist[x]
                q[right] = i
                right = right + 1
            elif dist[i] == dist[x]:
                good = False 
    far = 0
    for i in dist: 
        if far < i:
            far = i
    return good, far, dist

arr = [0] * n
